// One Telegram update per run, so .first() is this message.
const u = $('Normalise update').first().json;
const c = $input.first().json;                        // {} when the chat_id is new
const known = !!(c && c.chat_id && c.phone);
const text = String(u.text).trim();
let state = 'known', name = c.name || u.first_name || '', phone = c.phone || '';

if (text.toLowerCase().startsWith('/start')) {
  state = known ? 'start_known' : 'start_new';
} else if (!known) {
  // We asked for "Name, phone", e.g. "Ronke, 0800 000 0000"
  const d = text.replace(/\D/g, '');
  if (d.length >= 10) {
    phone = d.startsWith('234') ? '+' + d : d.startsWith('0') ? '+234' + d.slice(1) : '+234' + d;
    const n = text.replace(/[+\d][\d\s\-()]{6,}/g, ' ').replace(/[,;]/g, ' ').replace(/\s+/g, ' ').trim();
    if (n) name = n;
    state = 'register';
  } else {
    state = 'ask_details';
  }
}
return [{ json: { state, known, chat_id: u.chat_id, name, phone, area: c.area || '' } }];

