// Build the summary and a short pending ID (callback data must stay under 64 bytes).
const p = $input.first().json;
const u = $('Normalise update').first().json;
const naira = n => '₦' + Number(n).toLocaleString('en-NG');
const pending_id = 'P' + Date.now().toString(36).toUpperCase();
const day = DateTime.fromISO(p.delivery_date).toFormat('cccc d LLL');
const summary = [
  'Here is your order:',
  ...p.lines.map(l => `• ${l.qty} ${l.unit} ${l.name} × ${naira(l.price)} = ${naira(l.line_total)}`),
  `Subtotal: ${naira(p.subtotal)}`,
  `Delivery: ${p.delivery_fee ? naira(p.delivery_fee) : 'free'}`,
  `Total: ${naira(p.total)}`,
  `Delivery day: ${day}, ${p.area}`,
  'Tap ✅ Confirm to place it, or ✏️ Change.',
].join('\n');
return [{ json: {
  pending_id, chat_id: u.chat_id, summary, total: p.total,
  items_json: JSON.stringify({ lines: p.lines, subtotal: p.subtotal, delivery_fee: p.delivery_fee,
                               delivery_date: p.delivery_date, area: p.area }),
} }];

