// Answer from Price_List only. Same alias matching as SUB · Price an order.
const text = String($('Normalise update').first().json.text).toLowerCase();
const products = $input.all().map(i => i.json).filter(p => p.active !== 'no');
const hits = products.filter(p =>
  String(p.aliases).toLowerCase().split(',').map(a => a.trim()).some(a => a && text.includes(a)));
const naira = n => '₦' + Number(n).toLocaleString('en-NG');
const reply = hits.length
  ? hits.map(p => `${p.name}: ${naira(p.price)} per ${p.unit} (${Number(p.stock) > 0 ? p.stock + ' in stock' : 'out of stock'})`).join('\n')
    + "\nPrices from today's list. Send your order any time!"
  : "I couldn't find that on today's price list. Tolu will reply shortly.";
return [{ json: { reply, found: hits.length } }];

// Is this tap valid, for this chat, on a row that's still open?
const u = $('Normalise update').first().json;
const tap = $('Parse tap').first().json;
const row = $input.first().json;
let decision;
if (!row || !row.pending_id || String(row.chat_id) !== String(u.chat_id)) decision = 'invalid';
else if (row.status !== 'open') decision = 'already';          // double tap, or already handled
else decision = tap.action === 'c' ? 'confirm' : tap.action === 'x' ? 'change' : 'invalid';
return [{ json: { decision, ...row } }];

// Re-read stock at the moment of Confirm (another customer may have bought it).
const pend = $('Check pending').first().json;
const order = JSON.parse(pend.items_json);
const stock = {};
for (const { json: p } of $input.all()) stock[p.sku] = Number(p.stock);
const short = order.lines.filter(l => !(stock[l.sku] >= l.qty));
return [{ json: {
  ok: short.length === 0,
  order_id: 'HL-' + Date.now().toString().slice(-6),
  pending_id: pend.pending_id, chat_id: pend.chat_id,
  items_json: JSON.stringify(order.lines),
  subtotal: order.subtotal, delivery_fee: order.delivery_fee, total: Number(pend.total),
  delivery_date: order.delivery_date, area: order.area,
  stock_updates: order.lines.map(l => ({ sku: l.sku, stock: stock[l.sku] - l.qty })),
  short: short.map(l => `${l.name}: only ${stock[l.sku] ?? 0} ${l.unit}(s) left`),
} }];

